parameters.functionCode:
const events = $input.all().map(i => i.json);
if (!events.length || !events[0].id) return [];

const results = [];

for (const event of events) {
  let subject, templateId, scoreImpact;

  switch (event.event_type) {
    case 'birthday':
      subject = `🎂 Happy Birthday, ${event.first_name || 'there'}! Here's a special gift`;
      templateId = 'd-event-birthday';
      scoreImpact = 5;
      break;
    case 'anniversary':
      const years = Math.floor((Date.now() - new Date(event.created_at).getTime()) / (365.25 * 24 * 60 * 60 * 1000));
      subject = `🎉 ${event.first_name || 'Hi'}, it's been ${years} year${years > 1 ? 's' : ''}! Thank you`;
      templateId = 'd-event-anniversary';
      scoreImpact = 3;
      break;
    case 'trial_expiring':
      subject = `⏰ ${event.first_name || 'Hi'}, your trial expires in 3 days`;
      templateId = 'd-event-trial-expiring';
      scoreImpact = 10;
      break;
    default:
      subject = `${event.first_name || 'Hi'}, we have something for you`;
      templateId = 'd-event-generic';
      scoreImpact = 2;
  }

  results.push({
    json: {
      ...event,
      email_subject: subject,
      template_id: templateId,
      score_impact: scoreImpact
    }
  });
}

return results;

